/**
 * Shader des rayons volumetriques.
 *
 * ## L'idee mathematique
 *
 * Un faisceau n'est visible que s'il traverse quelque chose : ici une brume
 * de bruit fractal qui derive. Le masque des rais est un bruit 1D de l'angle
 * autour du foyer, comme pour les rayons ; mais la lumiere qui atteint un
 * fragment est integree le long du rai — une marche a pas constants du
 * fragment vers le foyer, qui somme la brume traversee. Une brume epaisse en
 * amont eteint le rai ; une brume locale le diffuse. C'est ce qui distingue
 * ces rais des rayons plats : ils ont un volume, ils s'eteignent derriere un
 * banc de brume et s'allument dans le suivant.
 *
 * La lumiere se pose par melange borne vers ses teintes : la brume tient sur
 * un fond clair comme sur un fond sombre.
 *
 * ## Uniforms
 *
 * - `uTime` — temps en secondes, fourni par le moteur.
 * - `uResolution` — taille du canevas en pixels, fournie par le moteur.
 * - `uColorA` — le fond.
 * - `uColorB` — la lumiere des rais.
 * - `uColorC` — la teinte de la brume et du foyer.
 * - `uX`, `uY` — position du foyer, en fraction du cadre.
 * - `uCount` — nombre de rais sur le tour.
 * - `uStrength` — intensite de la lumiere.
 * - `uSamples` — nombre de pas de la marche, et donc le cout.
 */
export const VOLUMETRIC_RAYS_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uX;
uniform float uY;
uniform float uCount;
uniform float uStrength;
uniform float uSamples;

float brumeHash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float brumeNoise(vec2 p) {
  vec2 cell = floor(p);
  vec2 local = fract(p);
  vec2 smoothed = local * local * (3.0 - 2.0 * local);

  float a = brumeHash(cell);
  float b = brumeHash(cell + vec2(1.0, 0.0));
  float c = brumeHash(cell + vec2(0.0, 1.0));
  float d = brumeHash(cell + vec2(1.0, 1.0));

  return mix(mix(a, b, smoothed.x), mix(c, d, smoothed.x), smoothed.y);
}

// Deux octaves suffisent a la brume : elle est lue a chaque pas de la marche,
// et c'est la marche qui lisse.
float brume(vec2 p, float t) {
  vec2 q = p * 1.6 + vec2(t * 0.06, -t * 0.02);
  return brumeNoise(q) * 0.65 + brumeNoise(q * 2.1 + vec2(1.7, 4.3) + vec2(-t * 0.04, 0.0)) * 0.35;
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vec2(vUv.x * aspect, vUv.y);
  vec2 foyer = vec2(uX * aspect, uY);
  float t = uTime;
  int pas = int(clamp(uSamples, 2.0, 16.0));

  vec2 ecart = p - foyer;
  float rayon = length(ecart);
  float angle = atan(ecart.y, ecart.x);

  // Le masque angulaire : deux sinus de frequences entieres non multiples,
  // sans couture sur le tour, dont les phases derivent lentement.
  float f1 = max(floor(uCount), 2.0);
  float f2 = floor(f1 * 1.9) + 1.0;
  float rai = pow(0.5 + 0.5 * sin(angle * f1 + t * 0.12), 3.0) * 0.7
    + pow(0.5 + 0.5 * sin(angle * f2 - t * 0.09), 3.0) * 0.5;

  // La marche : du fragment vers le foyer, la brume traversee s'accumule.
  vec2 enjambee = -ecart / float(pas) * 0.9;
  vec2 s = p;
  float epaisseur = 0.0;
  for (int i = 0; i < 16; i += 1) {
    if (i >= pas) break;
    s += enjambee;
    epaisseur += brume(s, t);
  }
  epaisseur /= float(pas);

  // La transmission : une brume epaisse en amont eteint le rai. La borne
  // basse garde un peu de lumiere partout, sinon le cadre se coupe en deux.
  float transmission = 1.0 - smoothstep(0.35, 0.65, epaisseur) * 0.9;

  // La diffusion : c'est la brume locale qui rend le rai visible.
  float locale = brume(p, t);
  float diffusion = 0.2 + 0.8 * locale;

  float lumiere = rai * transmission * diffusion * exp(-rayon * 1.1) * max(uStrength, 0.0) * 1.3;
  float source = exp(-rayon * rayon * 7.0) * (0.5 + 0.2 * rai);

  vec3 colour = mix(uColorA, uColorC, clamp(locale * 0.22 + source * 0.6, 0.0, 1.0));
  colour = mix(colour, uColorB, clamp(lumiere, 0.0, 1.0));

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Rayons volumetriques : des rais de lumiere integres a travers une brume.
 *
 * ## Le principe
 *
 * Le masque des rais est un bruit de l'angle autour du foyer, mais la lumiere
 * qui atteint un fragment est integree le long du rai par une marche vers le
 * foyer, a travers une brume qui derive. Un banc epais eteint le rai, la
 * brume locale le diffuse. Distinct des rayons plats : les rais ont un volume
 * et se coupent derriere la brume.
 *
 * ## Ce que ce composant delegue
 *
 * Il ne porte que ce qui le distingue : son shader, ses reglages et son repli.
 * La lecture des tokens, leur conversion en flottants et leur relecture au
 * changement de theme viennent du moteur.
 *
 * Le repli n'est pas une precaution : il est affiche pendant le chargement du
 * backend, quand WebGL manque, quand l'arbitre refuse la surface et sous
 * mouvement reduit.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { VOLUMETRIC_RAYS_FRAGMENT } from './volumetric-rays.shader.js'

/** Ce que l'echappatoire recoit. */
export interface VolumetricRaysControls {
  /** Couleurs effectivement transmises au shader. */
  readonly colours: readonly ShaderColour[]
  /** Motif du refus, s'il y en a un. */
  readonly refused: string | undefined
}

/** Proprietes propres au composant. */
export interface VolumetricRaysOwnProps {
  /** Position horizontale du foyer, en fraction du cadre. @defaultValue 0.5 */
  x?: number
  /** Position verticale du foyer, en fraction du cadre. @defaultValue 1 */
  y?: number
  /** Nombre de rais sur le tour. @defaultValue 10 */
  count?: number
  /** Intensite de la lumiere. @defaultValue 1 */
  strength?: number
  /** Tokens dont les couleurs sont lues. */
  colors?: readonly string[]
  /** Classes du repli. */
  fallback?: string
  /** Echappatoire. */
  onReady?: ReadyCallback<VolumetricRaysControls>
}

/** Toutes les proprietes. */
export type VolumetricRaysProps = Customisable<VolumetricRaysOwnProps>

/** Tokens employes par defaut : le fond, la lumiere, la brume. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-amber-300',
  '--o-palette-orange-500',
] as const

/** Repli par defaut : un degrade fige, dans les memes tons. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-b o-from-amber-100 dark:o-from-amber-900 o-to-zinc-50 dark:o-to-zinc-950'

/**
 * Pas de la marche hors qualite basse.
 *
 * Chaque pas lit la brume une fois : c'est le seul levier de cout du shader.
 * Douze pas suffisent a integrer sans bandes ; en dessous de cinq, les bancs
 * de brume se hachent.
 */
const SAMPLES = 12

/** Pas de la marche en qualite basse. */
const LOW_SAMPLES = 5

/**
 * Rayons volumetriques.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <VolumetricRays className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function VolumetricRays({
  x = 0.5,
  y = 1,
  count = 10,
  strength = 1,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: VolumetricRaysProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: VOLUMETRIC_RAYS_FRAGMENT,
    colors,
    uniforms: { uX: x, uY: y, uCount: count, uStrength: strength, uSamples: SAMPLES },
    name: 'volumetric-rays',
    degrade: (quality) => ({
      uSamples: quality === 'low' ? LOW_SAMPLES : SAMPLES,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
